/**
 * Minimal service worker: caches the app shell so the installed PWA opens
 * offline, without ever caching API responses (receipts/settings must
 * always be fresh, and extract/estimate must never be cached).
 *
 * This is hand-written rather than generated by a plugin (e.g. next-pwa)
 * to avoid adding a new dependency for a phase whose only requirement is
 * "installable on a phone home screen" — see Phase 8 in the build plan.
 */
const CACHE_NAME = "crumb-trail-shell-v1";
const SHELL_URLS = ["/", "/manifest.webmanifest", "/icons/icon-512.png"];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(SHELL_URLS)),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))),
      ),
  );
  self.clients.claim();
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);

  if (request.method !== "GET" || url.pathname.startsWith("/api/")) {
    return; // never intercept API calls — always go straight to the network
  }

  event.respondWith(
    fetch(request)
      .then((response) => {
        const copy = response.clone();
        caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));
        return response;
      })
      .catch(() => caches.match(request)),
  );
});
